SINA_SMART["anat1-thorax-overview"] = {"lecture":"anat1-thorax-overview","title":"Thorax part 1: overview","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-thorax-overview:e0","text":"Thorax: superior aperture (open to neck), inferior aperture (closed by diaphragm).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-overview:e1","text":"Three compartments: two pleural cavities + mediastinum.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-overview:e2","text":"Pleural cavities extend above rib 1.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-overview:e3","text":"Sternal angle = rib 2 = T4-T5.","topic":"Surface anatomy and wall","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-overview:e4","text":"Lines: midsternal, midclavicular, anterior/mid/posterior axillary.","topic":"Surface anatomy and wall","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-overview:e5","text":"Superior aperture: T1, first ribs, manubrium.","topic":"Apertures and diaphragm","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-overview:e6","text":"Inferior aperture: T12, ribs 11-12, costal cartilages 7-10, xiphoid.","topic":"Apertures and diaphragm","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-overview:e7","text":"Right dome of diaphragm higher (rib 5); oesophagus and IVC pierce it, aorta passes behind.","topic":"Apertures and diaphragm","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-overview:e8","text":"Mediastinum: superior / inferior (anterior, middle, posterior) at the sternal angle plane.","topic":"Mediastinum and pleural cavities","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-overview:e9","text":"Parietal and visceral pleura; costodiaphragmatic recess is the largest.","topic":"Mediastinum and pleural cavities","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1mon1uy":"a","5201t5":"a","9jdf3r":"a","1qwnbt4":"a","9iid1z":"a","1wdomdx":"a","jid9yl":"a","3gb1y":"a","9hcjln":"a","ovwt9l":"a","12vlm7x":"a","1gh33fs":"a"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-thorax-overview:e0":{"s":0,"u":["Thorax: superior aperture (open to neck), inferior aperture (closed by diaphragm).","The thorax is an irregular cylinder with a narrow superior thoracic aperture (open, continuous with the neck) and a wide inferior thoracic aperture closed by the diaphragm ."],"dp":[{"h":"Note","t":"The right dome of the diaphragm is higher (liver), reaching about rib 5. The inferior aperture is closed by the diaphragm; the superior aperture is open to the neck."}]},"anat1-thorax-overview:e1":{"s":0,"u":["Three compartments: two pleural cavities + mediastinum.","The pleural cavities extend above rib 1 into the neck.","Its cavity has three compartments: right and left pleural cavities (each around a lung) and the central mediastinum , which completely separates them and contains the heart, oesophagus, trachea, major nerves and great vessels."],"dp":[]},"anat1-thorax-overview:e2":{"s":0,"u":["Pleural cavities extend above rib 1.","The pleural cavities extend above rib 1 into the neck.","Its cavity has three compartments: right and left pleural cavities (each around a lung) and the central mediastinum , which completely separates them and contains the heart, oesophagus, trachea, major nerves and great vessels."],"dp":[{"h":"Why a needle above the clavicle can collapse a lung","t":"The dome of the pleura and the apex of the lung rise above the first rib into the root of the neck. A needle inserted just above the clavicle, for a central venous line or a nerve block, can puncture the pleura and let air in, causing a pneumothorax. Knowing that the pleural cavities extend above rib 1 is the safety point. Source: the lecture's general description."}]},"anat1-thorax-overview:e3":{"s":1,"u":["Sternal angle = rib 2 = T4-T5.","Landmarks: clavicles (manubrium to acromion), jugular notch between their medial ends, sternal angle (of Louis) between manubrium and body, where rib 2 articulates, at the T4-T5 level."],"dp":[{"h":"Note","t":"Sternal angle (of Louis) = 2nd rib = T4/T5 disc: start and end of the aortic arch, tracheal bifurcation, superior/inferior mediastinum border. Count ribs from here."}]},"anat1-thorax-overview:e4":{"s":1,"u":["Lines: midsternal, midclavicular, anterior/mid/posterior axillary.","Vertical lines: midsternal , midclavicular (just medial to the nipple), anterior axillary (pectoralis major fold), midaxillary , posterior axillary (latissimus dorsi fold)."],"dp":[]},"anat1-thorax-overview:e5":{"s":2,"u":["Superior aperture: T1, first ribs, manubrium.","Superior aperture : body of T1 , medial margins of the first ribs, and the manubrium (upper margin at the T2-T3 disc level); tilted forward; head and neck structures pass through it vertically, upper limb structures pass over rib 1."],"dp":[]},"anat1-thorax-overview:e6":{"s":2,"u":["Inferior aperture: T12, ribs 11-12, costal cartilages 7-10, xiphoid.","Inferior aperture : body of T12 , rib 12 and the end of rib 11, cartilages of ribs 7-10 (costal margin), and the xiphoid process ; the xiphisternal joint lies at the T9-T10 disc level; the posterior margin is lower than the anterior."],"dp":[{"h":"Memory aid","t":"Diaphragm openings: 'I 8 10 Eggs At 12' : I VC at T8 , E sophagus at T10 , A orta at T12 ."}]},"anat1-thorax-overview:e7":{"s":2,"u":["Right dome of diaphragm higher (rib 5); oesophagus and IVC pierce it, aorta passes behind.","The oesophagus and inferior vena cava pierce it; the aorta passes behind it.","The diaphragm arises radially from the margins and converges on a central tendon ; it forms two domes, the right higher (up to rib 5, above the liver)."],"dp":[]},"anat1-thorax-overview:e8":{"s":3,"u":["Mediastinum: superior / inferior (anterior, middle, posterior) at the sternal angle plane.","A plane through the sternal angle and the T4-T5 disc divides it into superior and inferior parts; the inferior is split by the pericardium into anterior (sternum to pericardium), middle (pericardium and heart) and posterior (pericardium to vertebrae).","The mediastinum runs from sternum to vertebrae and from the superior to the inferior aperture."],"dp":[{"h":"Note","t":"Mediastinum : superior (above the T4/T5 plane) and inferior, the latter split by the pericardium into anterior, middle (heart) and posterior ."}]},"anat1-thorax-overview:e9":{"s":3,"u":["Parietal and visceral pleura; costodiaphragmatic recess is the largest.","Each pleural cavity is lined by pleura: parietal pleura on the walls, reflecting at the lung root (airway, pulmonary vessels, lymphatics, nerves) into visceral pleura on the lung, with only a potential space between them.","The lungs do not fill the cavity completely, leaving recesses for expansion; the largest and clinically most important is the costodiaphragmatic recess , where fluid collects (pleural effusion)."],"dp":[{"h":"Clinical","t":"Pleura and lungs reach above rib 1 into the neck: a needle in the supraclavicular region (central line, nerve block) can cause a pneumothorax ."},{"h":"Clinical","t":"Costodiaphragmatic recess is the lowest part of the pleural cavity: pleural effusions collect there first (blunted costophrenic angle on X-ray)."}]}},"meta":{"1mon1uy":{"a":"recall","vg":"anat1-thorax-overview:e3/recall/1"},"5201t5":{"a":"recall","vg":"anat1-thorax-overview:e3/recall/2"},"9jdf3r":{"a":"recall","vg":"anat1-thorax-overview:e4/recall/1"},"1qwnbt4":{"a":"recall","vg":"anat1-thorax-overview:e0/recall/1"},"9iid1z":{"a":"recall","vg":"anat1-thorax-overview:e5/recall/1"},"1wdomdx":{"a":"recall","vg":"anat1-thorax-overview:e7/recall/1"},"jid9yl":{"a":"recall","vg":"anat1-thorax-overview:e7/recall/2"},"3gb1y":{"a":"recall","vg":"anat1-thorax-overview:e8/recall/1"},"9hcjln":{"a":"recall","vg":"anat1-thorax-overview:e8/recall/2"},"ovwt9l":{"a":"recall","vg":"anat1-thorax-overview:e9/recall/1"},"12vlm7x":{"a":"recall","vg":"anat1-thorax-overview:e9/recall/2"},"1gh33fs":{"a":"recall","vg":"anat1-thorax-overview:e2/recall/1"}},"explRev":"e893e4913fd8"};
